using Backend.BDFolder;using Backend.Models;using Backend.Services;using FluentValidation;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace Backend.Controllers;[ApiController][Route("api/[controller]")]public class AutenticacionController(    TransportesRojasDbContext contexto,    IValidator<LoginClienteModel> validadorCliente,    IValidator<LoginEmpleadoModel> validadorEmpleado,    JwtService jwtService) : ControllerBase{    private readonly PasswordHasher<object> _passwordHasher = new();    [HttpPost("login-cliente")]    public async Task<IActionResult> LoginCliente([FromBody] LoginClienteModel model)    {        if (model is null)            return BadRequest(new { mensaje = "El cuerpo de la solicitud no puede estar vacío." });        var validacion = await validadorCliente.ValidateAsync(model);        if (!validacion.IsValid)        {            return BadRequest(new            {                mensaje = "Datos de entrada no válidos",                errores = validacion.Errors.Select(e => e.ErrorMessage)            });        }        var usuario = await contexto.Usuarios            .Include(u => u.Cliente)            .Include(u => u.UsuarioRoles)                .ThenInclude(ur => ur.Rol)                    .ThenInclude(r => r.RolPermisos)                        .ThenInclude(rp => rp.Permiso)            .FirstOrDefaultAsync(u => u.Email == model.Email);        if (usuario is null)            return Unauthorized(new { mensaje = "Usuario o contraseña incorrectos" });        if (usuario.TipoUsuario != TipoUsuario.Cliente || usuario.Cliente is null)            return Unauthorized(new { mensaje = "Usuario o contraseña incorrectos" });        if (!usuario.Activo || !usuario.Cliente.Activo)            return Unauthorized(new { mensaje = "Usuario o contraseña incorrectos" });        var resultado = _passwordHasher.VerifyHashedPassword(new { }, usuario.PasswordHash, model.Password);        if (resultado == PasswordVerificationResult.Failed)            return Unauthorized(new { mensaje = "Usuario o contraseña incorrectos" });        usuario.UltimoAcceso = DateTimeOffset.UtcNow;        await contexto.SaveChangesAsync();        var nombreCompleto = $"{usuario.Cliente.Nombre} {usuario.Cliente.ApellidoPaterno} {usuario.Cliente.ApellidoMaterno}".Trim();        if (string.IsNullOrWhiteSpace(nombreCompleto))            nombreCompleto = usuario.Email;        var roles = usuario.UsuarioRoles            .Select(ur => ur.Rol.Nombre)            .Distinct()            .ToList();        if (roles.Count == 0)        {            roles.Add("Cliente");        }        var permisos = usuario.UsuarioRoles            .SelectMany(ur => ur.Rol.RolPermisos)            .Select(rp => rp.Permiso.Codigo)            .Distinct()            .ToList();        var token = jwtService.GenerarTokenCliente(            usuario,            usuario.Cliente,            roles,            permisos        );        return Ok(new LoginResponse(            usuario.Id,            usuario.Email,            usuario.TipoUsuario.ToString(),            nombreCompleto,            usuario.Cliente.Id,            token,            roles,            permisos        ));    }    [HttpPost("login-empleado")]    public async Task<IActionResult> LoginEmpleado([FromBody] LoginEmpleadoModel model)    {        if (model is null)            return BadRequest(new { mensaje = "El cuerpo de la solicitud no puede estar vacío." });        var validacion = await validadorEmpleado.ValidateAsync(model);        if (!validacion.IsValid)        {            return BadRequest(new            {                mensaje = "Datos de entrada no válidos",                errores = validacion.Errors.Select(e => e.ErrorMessage)            });        }        var empleado = await contexto.Empleados            .Include(e => e.Usuario)                .ThenInclude(u => u.UsuarioRoles)                    .ThenInclude(ur => ur.Rol)                        .ThenInclude(r => r.RolPermisos)                            .ThenInclude(rp => rp.Permiso)            .Include(e => e.Sucursal)            .Include(e => e.PuestoHistorial)                .ThenInclude(ph => ph.Puesto)            .FirstOrDefaultAsync(e => e.Id == model.EmpleadoId);        if (empleado is null || empleado.Usuario is null)            return Unauthorized(new { mensaje = "Credenciales incorrectas" });        if (!empleado.Activo || !empleado.Usuario.Activo)            return Unauthorized(new { mensaje = "Credenciales incorrectas" });        var resultado = _passwordHasher.VerifyHashedPassword(new { }, empleado.Usuario.PasswordHash, model.Password);        if (resultado == PasswordVerificationResult.Failed)            return Unauthorized(new { mensaje = "Credenciales incorrectas" });        empleado.Usuario.UltimoAcceso = DateTimeOffset.UtcNow;        await contexto.SaveChangesAsync();        var nombreCompleto = $"{empleado.Nombre} {empleado.ApellidoPaterno} {empleado.ApellidoMaterno}".Trim();        if (string.IsNullOrWhiteSpace(nombreCompleto))            nombreCompleto = empleado.Usuario.Email;        var roles = empleado.Usuario.UsuarioRoles            .Select(ur => ur.Rol.Nombre)            .Distinct()            .ToList();        var permisos = empleado.Usuario.UsuarioRoles            .SelectMany(ur => ur.Rol.RolPermisos)            .Select(rp => rp.Permiso.Codigo)            .Distinct()            .ToList();        var puestoActual = empleado.PuestoHistorial            .Where(ph => ph.FechaFin == null)            .OrderByDescending(ph => ph.FechaInicio)            .Select(ph => ph.Puesto.Nombre)            .FirstOrDefault();        var token = jwtService.GenerarTokenEmpleado(            empleado.Usuario,            empleado,            roles,            permisos,            puestoActual        );        return Ok(new LoginResponse(            empleado.Usuario.Id,            empleado.Usuario.Email,            empleado.Usuario.TipoUsuario.ToString(),            nombreCompleto,            empleado.Id,            token,            roles,            permisos,            puestoActual,            empleado.Sucursal?.Nombre        ));    }}